#!/bin/bash
dnf update -y
dnf install -y nodejs
mkdir -p /opt/app
echo "" | base64 -d > /opt/app/app.js
echo "ewogICJuYW1lIjogInVwbG9hZGVyLWFwcCIsCiAgInZlcnNpb24iOiAiMS4wLjAiLAogICJtYWluIjogImFwcC5qcyIsCiAgImRlcGVuZGVuY2llcyI6IHsKICAiZXhwcmVzcyI6ICJeNC4xOS4yIiwKICAibXVsdGVyIjogIl4xLjQuNS1sdHMuMSIsCiAgIkBhd3Mtc2RrL2NsaWVudC1zMyI6ICJeMy42MDAuMCIKIH0KfQo=" | base64 -d > /opt/app/package.json
cd /opt/app
npm install --omit=dev
cat > /etc/systemd/system/uploader.service << 'SERVICE'
[Unit]
Description=Uploader App
After=network.target
[Service]
Environment=BUCKET_NAME=itmo-544-cesar2005-fileshare
Environment=AWS_REGION=us-east-2
Environment=PORT=3000
WorkingDirectory=/opt/app
ExecStart=/usr/bin/node /opt/app/app.js
Restart=always
User=ec2-user
[Install]
WantedBy=multi-user.target
SERVICE
chown -R ec2-user:ec2-user /opt/app
systemctl daemon-reload
systemctl enable uploader.service
systemctl start uploader.service
